import{window as i}from"ssr-window";export default function(r){if(!r)return;let a=!1;const n=Object.keys(r).map(e=>{if(typeof e=="string"&&e.indexOf("@")===0){const t=parseFloat(e.substr(1));return{value:i.innerHeight*t,point:e}}return{value:e,point:e}});n.sort((e,t)=>parseInt(e.value,10)-parseInt(t.value,10));for(let e=0;e<n.length;e+=1){const{point:t,value:u}=n[e];u<=i.innerWidth&&(a=t)}return a||"max"}
